const assert = require('node:assert/strict');

        const { ProfileService } = require('../.build/service');
        const service = new ProfileService({ displayName: 'before', tags: ['old'] });
        assert.deepEqual(service.patch({ displayName: 'after' }), { displayName: 'after', tags: ['old'] });
        assert.deepEqual(service.patch({ tags: ['new'] }), { displayName: 'after', tags: ['new'] });
        assert.throws(() => service.patch(null), /invalid profile/);

// --- PATCH contract ---
const INVALID = /^invalid profile$/;
const fresh = (displayName = 'Ada', tags = ['x']) => new ProfileService({ displayName, tags });
const bad = (svc, input) => {
  const before = JSON.stringify(svc.profile);
  assert.throws(() => svc.patch(input), (e) => e instanceof Error && INVALID.test(e.message));
  assert.equal(JSON.stringify(svc.profile), before, 'storage must be unchanged on rejection');
};

// Input shape
{
  const s = fresh();
  for (const input of [undefined, 0, 1, 'x', true, [], [{}], null]) bad(s, input);
  bad(s, Object.create({ displayName: 'x' })); // displayName only inherited
  class Foo { constructor() { this.displayName = 'x'; } }
  bad(s, new Foo()); // non-Object prototype
  bad(s, new Date());
  bad(s, Object.assign(Object.create(Array.prototype), { displayName: 'x' }));
  bad(s, { displayName: 'x', extra: 1 });
  bad(s, { displayName: 'x', [Symbol('s')]: 1 });
  bad(s, JSON.parse('{"__proto__": {"x": 1}}'));
  bad(s, Object.defineProperty({}, 'tags', { get() { return []; }, enumerable: true }));
  bad(s, Object.defineProperty({}, 'hidden', { value: 1, enumerable: false }));
}

// Empty object and null-prototype objects
{
  const s = fresh('Ada', ['x']);
  assert.deepEqual(s.patch({}), { displayName: 'Ada', tags: ['x'] });
  const np = Object.create(null);
  np.displayName = 'Bob';
  assert.deepEqual(s.patch(np), { displayName: 'Bob', tags: ['x'] });
}

// displayName
{
  const s = fresh();
  assert.deepEqual(s.patch({ displayName: '  Ada  ' }).displayName, 'Ada');
  assert.equal(s.patch({ displayName: 'a'.repeat(40) }).displayName, 'a'.repeat(40));
  assert.equal(s.patch({ displayName: null }).displayName, null);
  assert.deepEqual(s.profile.tags, ['x'], 'absent tags retain stored value');
  for (const v of ['', '   ', 'a'.repeat(41), ' ' + 'a'.repeat(40) + ' x', 5, 0, true, false, undefined, {}, ['A'], new String('x')]) {
    bad(s, { displayName: v });
  }
  bad(s, { displayName: 5 });
}

// tags
{
  const s = fresh();
  assert.deepEqual(s.patch({ tags: ['  a ', 'b'] }).tags, ['a', 'b']);
  assert.deepEqual(s.patch({ tags: null }).tags, []);
  assert.deepEqual(s.patch({ tags: ['z'] }).tags, ['z']);
  assert.deepEqual(s.patch({ tags: [] }).tags, []);
  assert.deepEqual(s.patch({ tags: ['1', 'a', 'b', 'c', 'd'] }).tags, ['1', 'a', 'b', 'c', 'd']);
  assert.deepEqual(s.patch({ tags: ['a'.repeat(12)] }).tags, ['a'.repeat(12)]);
  assert.deepEqual(s.patch({ tags: [' ' + 'a'.repeat(12) + ' '] }).tags, ['a'.repeat(12)]);
  bad(s, { tags: ['a', 'b', 'c', 'd', 'e', 'f'] });
  bad(s, { tags: ['a', ' a '] }); // duplicate after trim
  bad(s, { tags: ['   '] });
  bad(s, { tags: [''] });
  bad(s, { tags: ['a'.repeat(13)] });
  bad(s, { tags: [' ' + 'a'.repeat(12) + ' x'] });
  bad(s, { tags: [1] });
  bad(s, { tags: ['a', null] });
  bad(s, { tags: ['a', undefined] });
  bad(s, { tags: 'a' });
  bad(s, { tags: { 0: 'a', length: 1 } });
  bad(s, { tags: undefined });
  const holey = new Array(2); holey[0] = 'a';
  bad(s, { tags: holey });
}

// Caller arrays are not stored or mutated
{
  const s = fresh();
  const t = ['a', 'b'];
  const input = { tags: t };
  const out = s.patch(input);
  assert.notEqual(out.tags, t);
  t.push('c');
  assert.deepEqual(out.tags, ['a', 'b']);
  assert.deepEqual(input, { tags: ['a', 'b', 'c'] });
  const dn = { displayName: '  Zed ' };
  s.patch(dn);
  assert.deepEqual(dn, { displayName: '  Zed ' });
}

// Mixed valid patch applies both fields; a failure in one field applies neither
{
  const s = fresh('Ada', ['x']);
  assert.deepEqual(s.patch({ displayName: 'Bo', tags: ['p', 'q'] }), { displayName: 'Bo', tags: ['p', 'q'] });
  bad(s, { displayName: 'Cy', tags: ['bad bad bad bad'.repeat(2)] });
  assert.deepEqual(s.profile, { displayName: 'Bo', tags: ['p', 'q'] });
}
console.log('public checks passed');
